import sqlite3


def handle(trusted_owner, body, db_path):
    # Validate body is a dict-like object with get method
    if not isinstance(body, dict):
        return {"status": 400, "text": None}

    # Validate body.key as nonempty string
    key = body.get("key")
    if not isinstance(key, str) or not key:
        return {"status": 400, "text": None}

    # Validate body.text as nonempty string
    text = body.get("text")
    if not isinstance(text, str) or not text:
        return {"status": 400, "text": None}

    # Use BEGIN IMMEDIATE to serialize writes and acquire lock early
    conn = sqlite3.connect(db_path, timeout=30.0)
    conn.execute("PRAGMA journal_mode=WAL")
    try:
        with conn:  # Auto-commit on success, rollback on exception
            conn.execute(
                "CREATE TABLE IF NOT EXISTS notes (owner TEXT, key TEXT, text TEXT, PRIMARY KEY(owner, key))"
            )

            # Try to insert; UNIQUE constraint will trigger ON CONFLICT
            try:
                conn.execute(
                    "INSERT INTO notes (owner, key, text) VALUES (?, ?, ?)",
                    (trusted_owner, key, text),
                )
                return {"status": 201, "text": text}
            except sqlite3.IntegrityError:
                # Conflict occurred; fetch existing row to determine replay vs conflict
                cursor = conn.execute(
                    "SELECT text FROM notes WHERE owner = ? AND key = ?",
                    (trusted_owner, key),
                )
                row = cursor.fetchone()
                if row is None:
                    # Should not happen; re-raise for safety
                    raise

                existing_text = row[0]
                if existing_text == text:
                    # Idempotent replay with identical payload
                    return {"status": 200, "text": existing_text}
                else:
                    # Conflict: different text for same owner/key
                    return {"status": 409, "text": None}
    finally:
        conn.close()

